"""OpenAI-compatible Grok Imagine image generation and editing node."""

from __future__ import annotations

import base64
import binascii
import json
import math
import urllib.error
import urllib.parse
import urllib.request
from io import BytesIO
from typing import Any

import torch

from ..core.grok_config import find_profile, profile_names


ASPECT_RATIOS = (
    "自动",
    "1:1",
    "16:9",
    "9:16",
    "4:3",
    "3:4",
    "3:2",
    "2:3",
    "2:1",
    "1:2",
    "19.5:9",
    "9:19.5",
    "20:9",
    "9:20",
    "21:9",
    "5:2",
)
# ``size`` is kept as a legacy workflow input.  The first value is the new
# safe default: when a ratio is selected, the ratio controls the request and
# a stale manual size cannot override it.
SIZES = ("自动跟随比例", "自动", "1024x1024", "1024x1536", "1536x1024")
RESOLUTIONS = ("1k", "2k")
QUALITIES = ("auto", "low", "medium")
NSFW_MODES = ("跟随配置", "开启（需服务端允许）", "关闭")
RESPONSE_FORMATS = ("b64_json", "url")
MODEL = "grok-imagine-image-2.0"
HTTP_USER_AGENT = "Wysl-ComfyUI-Tools/0.1"

def _ratio_from_size(size: str) -> str | None:
    return {
        "1024x1024": "1:1",
        "1024x1536": "2:3",
        "1536x1024": "3:2",
    }.get(str(size or "").strip().lower())


def _import_pillow():
    try:
        from PIL import Image
    except Exception as exc:  # pragma: no cover - depends on the ComfyUI runtime
        raise RuntimeError("Grok Imagine 节点需要 ComfyUI 已自带的 Pillow") from exc
    return Image


def _image_to_data_uri(image: torch.Tensor) -> str:
    Image = _import_pillow()
    if not isinstance(image, torch.Tensor):
        raise ValueError("图片输入必须是 IMAGE 张量")
    if image.ndim == 4:
        image = image[0]
    if image.ndim != 3 or image.shape[-1] < 3:
        raise ValueError("图片输入必须是 [B,H,W,C] 或 [H,W,C]，且至少有 3 个通道")
    pixels = image[..., :3].detach().to(device="cpu", dtype=torch.float32).clamp(0.0, 1.0)
    # Pillow is already a ComfyUI dependency. PNG keeps the reference image
    # lossless and avoids adding a second image codec dependency.
    pil_image = Image.fromarray((pixels.mul(255.0).round().byte().numpy()), mode="RGB")
    buffer = BytesIO()
    pil_image.save(buffer, format="PNG", optimize=True)
    encoded = base64.b64encode(buffer.getvalue()).decode("ascii")
    return f"data:image/png;base64,{encoded}"


def _data_uri_bytes(value: str) -> bytes | None:
    if not value.lower().startswith("data:"):
        return None
    header, separator, encoded = value.partition(",")
    if not separator or ";base64" not in header.lower():
        raise ValueError("Grok 返回的 data URI 不是 Base64 图片")
    try:
        return base64.b64decode(encoded, validate=True)
    except (ValueError, binascii.Error) as exc:
        raise ValueError("Grok 返回的图片 Base64 无效") from exc


def _image_bytes_from_item(item: Any, *, endpoint: str, api_key: str, timeout: float) -> bytes:
    if not isinstance(item, dict):
        raise ValueError("Grok 图片响应中的 data 项不是对象")
    encoded = item.get("b64_json") or item.get("blob")
    if isinstance(encoded, str) and encoded.strip():
        data_uri_bytes = _data_uri_bytes(encoded.strip())
        if data_uri_bytes is not None:
            return data_uri_bytes
        try:
            return base64.b64decode(encoded, validate=True)
        except (ValueError, binascii.Error) as exc:
            raise ValueError("Grok 图片响应中的 b64_json 无效") from exc

    url_value = item.get("url") or item.get("image_url")
    if isinstance(url_value, dict):
        url_value = url_value.get("url")
    if not isinstance(url_value, str) or not url_value.strip():
        raise ValueError("Grok 图片响应缺少 url 或 b64_json")
    direct_data = _data_uri_bytes(url_value.strip())
    if direct_data is not None:
        return direct_data
    url = urllib.parse.urljoin(endpoint, url_value.strip())
    if urllib.parse.urlsplit(url).scheme.lower() not in {"http", "https"}:
        raise ValueError("Grok 图片响应 URL 只支持 http 或 https")
    request = urllib.request.Request(
        url,
        headers={"Accept": "image/*", "User-Agent": HTTP_USER_AGENT},
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return response.read()
    except urllib.error.HTTPError as exc:
        # Some compatible gateways protect their own media URL with the same
        # bearer token. Retry only that URL, never a third-party URL.
        endpoint_host = urllib.parse.urlsplit(endpoint).netloc
        image_host = urllib.parse.urlsplit(url).netloc
        if exc.code in (401, 403) and api_key and endpoint_host == image_host:
            retry = urllib.request.Request(
                url,
                headers={
                    "Accept": "image/*",
                    "User-Agent": HTTP_USER_AGENT,
                    "Authorization": f"Bearer {api_key}",
                },
            )
            with urllib.request.urlopen(retry, timeout=timeout) as response:
                return response.read()
        raise RuntimeError(f"下载 Grok 图片失败（HTTP {exc.code}）") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"下载 Grok 图片失败：{exc.reason}") from exc


def _decode_image(raw: bytes) -> torch.Tensor:
    Image = _import_pillow()
    try:
        import numpy as np

        with Image.open(BytesIO(raw)) as image:
            rgb = image.convert("RGB")
            array = np.asarray(rgb, dtype=np.float32).copy() / 255.0
    except Exception as exc:
        raise ValueError(f"Grok 返回内容不是有效图片：{exc}") from exc
    return torch.from_numpy(array)


def _response_images(payload: Any) -> list[dict[str, Any]]:
    if not isinstance(payload, dict):
        raise ValueError("Grok 图片响应不是 JSON 对象")
    data = payload.get("data")
    if not isinstance(data, list) or not data:
        error = payload.get("error")
        if isinstance(error, dict):
            message = str(error.get("message", "Grok 图片请求失败"))
            raise RuntimeError(message[:500])
        raise RuntimeError("Grok 图片响应没有 data 图片")
    return [item for item in data if isinstance(item, dict)]


def _post_json(
    endpoint: str,
    api_key: str,
    payload: dict[str, Any],
    timeout: float,
) -> Any:
    if urllib.parse.urlsplit(endpoint).scheme.lower() not in {"http", "https"}:
        raise ValueError("Grok endpoint 只支持 http 或 https")
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "User-Agent": HTTP_USER_AGENT,
    }
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    request = urllib.request.Request(endpoint, data=body, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            response_body = response.read()
    except urllib.error.HTTPError as exc:
        try:
            detail = exc.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            detail = ""
        suffix = f": {detail}" if detail else ""
        raise RuntimeError(f"Grok 图片请求失败（HTTP {exc.code}）{suffix}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"连接 Grok endpoint 失败：{exc.reason}") from exc
    try:
        return json.loads(response_body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError("Grok endpoint 返回的不是有效 JSON") from exc


def _edits_endpoint(endpoint: str, configured: str) -> str:
    if configured.strip():
        return configured.strip()
    parsed = urllib.parse.urlsplit(endpoint)
    if parsed.path.rstrip("/").endswith("/generations"):
        path = parsed.path.rstrip("/")[:-len("generations")] + "edits"
        return urllib.parse.urlunsplit((parsed.scheme, parsed.netloc, path, parsed.query, parsed.fragment))
    return endpoint.rstrip("/") + "/edits"


def _payload_value(value: str, default: str = "") -> str | None:
    normalized = str(value or "").strip()
    return (
        None
        if not normalized
        or normalized in {"自动", "自动跟随比例"}
        or normalized.lower() == "auto"
        or normalized == default
        else normalized
    )


def _build_payload(
    profile_model: str,
    prompt: str,
    count: int,
    aspect_ratio: str,
    size: str,
    resolution: str,
    quality: str,
    response_format: str,
    nsfw_mode: str,
    profile_allow_nsfw: bool,
    image: torch.Tensor | None,
) -> dict[str, Any]:
    model = profile_model.strip() or MODEL
    payload: dict[str, Any] = {
        "model": model,
        "prompt": prompt,
        "n": int(count),
        "resolution": str(resolution).lower(),
        "response_format": str(response_format).lower(),
    }
    selected_ratio = _payload_value(aspect_ratio)
    selected_size = _payload_value(size)
    # A selected aspect ratio is authoritative.  Do not send an unrelated
    # legacy size alongside it: grok2api resolves the ratio first, while some
    # compatible gateways resolve the size first.  The official xAI API uses
    # aspect_ratio/resolution rather than size for image generation.
    if selected_ratio:
        payload["aspect_ratio"] = selected_ratio
    elif selected_size:
        mapped_ratio = _ratio_from_size(selected_size)
        if mapped_ratio:
            payload["aspect_ratio"] = mapped_ratio
        else:
            payload["size"] = selected_size
    selected_quality = _payload_value(quality)
    if selected_quality:
        payload["quality"] = selected_quality
    if nsfw_mode == "开启（需服务端允许）":
        nsfw_enabled = True
    elif nsfw_mode == "关闭":
        nsfw_enabled = False
    else:
        nsfw_enabled = bool(profile_allow_nsfw)
    # grok2api currently ignores these OpenAI-compatibility extras and uses
    # provider.web.allowNSFW; other compatible gateways may consume them.
    payload["enable_nsfw"] = nsfw_enabled
    payload["allow_nsfw"] = nsfw_enabled
    if image is not None:
        data_uri = _image_to_data_uri(image)
        payload["image"] = {"url": data_uri}
    return payload


class QQGrokImagineImage:
    CATEGORY = "QQ/图像生成"
    FUNCTION = "generate"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("图像",)
    DESCRIPTION = (
        "调用已配置的 OpenAI-compatible Grok2API 生成或编辑图片。"
        "API Key 只从外部配置读取，不会写入工作流。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "endpoint_profile": (profile_names(),),
                "prompt": ("STRING", {"multiline": True, "default": ""}),
                "model": ([MODEL], {"default": MODEL}),
                "aspect_ratio": (list(ASPECT_RATIOS), {"default": "自动"}),
                "size": (list(SIZES), {"default": "自动跟随比例"}),
                "resolution": (list(RESOLUTIONS), {"default": "1k"}),
                "quality": (list(QUALITIES), {"default": "auto"}),
                "count": ("INT", {"default": 1, "min": 1, "max": 10, "step": 1}),
                "response_format": (list(RESPONSE_FORMATS), {"default": "b64_json"}),
                "nsfw_mode": (list(NSFW_MODES), {"default": "跟随配置"}),
                "timeout": ("FLOAT", {"default": 300.0, "min": 5.0, "max": 3600.0, "step": 1.0}),
            },
            "optional": {"image": ("IMAGE",)},
        }

    @staticmethod
    def generate(
        endpoint_profile: str,
        prompt: str,
        model: str = MODEL,
        aspect_ratio: str = "自动",
        size: str = "自动",
        resolution: str = "1k",
        quality: str = "auto",
        count: int = 1,
        response_format: str = "b64_json",
        nsfw_mode: str = "跟随配置",
        timeout: float = 300.0,
        image: torch.Tensor | None = None,
    ):
        prompt = str(prompt or "").strip()
        if not prompt:
            raise ValueError("Grok Imagine 提示词不能为空")
        count = int(count)
        if count < 1 or count > 10:
            raise ValueError("图片数量必须在 1 到 10 之间")
        timeout = float(timeout)
        if not math.isfinite(timeout) or timeout <= 0:
            raise ValueError("请求超时必须是正数")
        if image is not None and int(image.shape[0]) > 8:
            raise ValueError("Grok 图片编辑最多接受 8 张参考图")

        profile = find_profile(endpoint_profile)
        payload = _build_payload(
            profile.model if model == MODEL else str(model),
            prompt,
            count if image is None else 1,
            aspect_ratio,
            size,
            resolution,
            quality,
            response_format,
            nsfw_mode,
            profile.allow_nsfw,
            None,
        )
        if image is None:
            response_payload = _post_json(profile.endpoint, profile.api_key, payload, timeout)
        else:
            edit_payload = dict(payload)
            edit_payload.pop("enable_nsfw", None)
            edit_payload.pop("allow_nsfw", None)
            # grok2api's /v1/images/edits contract rejects a non-empty
            # quality field; quality is a generation-only control there.
            edit_payload.pop("quality", None)
            # grok2api's Web image-edit path currently accepts only 1k.  The
            # requested 2k output is applied locally after the response.
            edit_payload["resolution"] = "1k"
            edit_payload["image"] = {"url": _image_to_data_uri(image[0:1])}
            if int(image.shape[0]) > 1:
                edit_payload.pop("image", None)
                edit_payload["images"] = [
                    {"url": _image_to_data_uri(image[index : index + 1])}
                    for index in range(int(image.shape[0]))
                ]
            response_payload = _post_json(
                _edits_endpoint(profile.endpoint, profile.edits_endpoint),
                profile.api_key,
                edit_payload,
                timeout,
            )

        decoded = [_decode_image(_image_bytes_from_item(item, endpoint=profile.endpoint, api_key=profile.api_key, timeout=timeout)) for item in _response_images(response_payload)]
        if not decoded:
            raise RuntimeError("Grok 没有返回可用图片")
        heights = {int(value.shape[0]) for value in decoded}
        widths = {int(value.shape[1]) for value in decoded}
        if len(heights) != 1 or len(widths) != 1:
            raise RuntimeError("Grok 返回的图片尺寸不一致，无法组成 ComfyUI IMAGE 批次")
        # Preserve the model's native pixels.  The official API is responsible
        # for applying aspect_ratio and resolution; local stretching would
        # deform people whenever a gateway ignores those fields.
        return (torch.stack(decoded, dim=0),)


NODE_CLASS_MAPPINGS = {"QQGrokImagineImage": QQGrokImagineImage}
NODE_DISPLAY_NAME_MAPPINGS = {"QQGrokImagineImage": "QQ-Grok图像生成"}
